// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 timestamp1, uint256 timestamp2, uint256 blockNum1, uint256 blockNum2) public {
        vm.assume(timestamp2 > timestamp1);
        vm.assume(blockNum2 > blockNum1);
        vm.assume(timestamp1 > 0);

        address sender = address(0x1234);
        vm.deal(sender, 20 ether);

        vm.warp(timestamp1);
        vm.roll(blockNum1);
        vm.prank(sender);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1, "first call failed");

        vm.warp(timestamp2);
        vm.roll(blockNum2);
        vm.prank(sender);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        require(ok2, "second call failed");

        assertEq(c.pastBlockTime(), timestamp2, "pastBlockTime should equal second call's timestamp");
    }
}
